package net.minecraft.world.item;public class ItemStack{public static final ItemStack EMPTY=new ItemStack("",0,64);public final String tag;private int count;public final int max;public ItemStack(String tag,int count,int max){this.tag=tag;this.count=count;this.max=max;}public Object name;public ItemStack(Item i){this("icon",1,64);}public Object set(Object key,Object v){name=v;return null;}public net.minecraft.nbt.Tag save(net.minecraft.core.HolderLookup.Provider p){net.minecraft.nbt.CompoundTag t=new net.minecraft.nbt.CompoundTag();t.putString("ItemTag",tag);t.putInt("Count",count);t.putInt("Max",max);return t;}public static ItemStack parseOptional(net.minecraft.core.HolderLookup.Provider p,net.minecraft.nbt.CompoundTag t){return new ItemStack(t.getString("ItemTag"),t.getInt("Count"),t.getInt("Max"));}public boolean isEmpty(){return count==0;}public int getCount(){return count;}public int getMaxStackSize(){return max;}public void setCount(int n){count=n;}public void grow(int n){count+=n;}public void shrink(int n){count-=n;}public ItemStack copyWithCount(int n){return new ItemStack(tag,n,max);}public ItemStack copy(){return new ItemStack(tag,count,max);}public ItemStack split(int n){int amount=Math.min(n,count);count-=amount;return new ItemStack(tag,amount,max);}public static boolean isSameItemSameComponents(ItemStack a,ItemStack b){return a.tag.equals(b.tag);}}
